const W = width, H = height, u = Math.min(W, H), diag = Math.sqrt(W * W + H * H), L = diag * 1.14;
const en = clp(P.energy, 0, 1), de = clp(P.density, 0, 1), sk = clp(P.streak, 0, 1);
const sp = Math.max(.1, P.speed), sc = Math.max(.35, P.scale);
const st = P.style, hb = ((P.hue % 360) + 360) % 360;
const la = clp(P.alpha, 0, 100) / 100;
const dc = drawingContext;

// ---- the ink library: offsets from P.hue, so hue rotates the whole shop -----
const INKS = st === 'metallic'
  ? [[248, 62, 78], [258, 12, 86], [230, 74, 62], [242, 40, 52], [252, 30, 90], [236, 55, 70]]
  : [[0, 92, 72], [127, 100, 74], [216, 96, 82], [31, 96, 44], [179, 96, 80], [134, 96, 66], [309, 92, 52], [38, 70, 46], [195, 10, 11], [210, 5, 92]];
