else if (P.act === 'build') cov = .55 + 1.10 * (.5 + .5 * Math.sin(K.t * .0067 + .8 * Math.sin(K.t * .0027 + 2.4)));
else cov = .84 + .34 * (.5 + .5 * Math.sin(K.t * .0091 + .5 * Math.sin(K.t * .0033 + 1.1)));
