// ---- stencil vocabulary (poster-shop geometry, hard cut edges) --------------
// NB: paths are built in device space, so save/transform/restore around the
// path commands leaves the subpaths correct and the CTM untouched afterwards.
const stencil = (arch, sd, cx, cy, R, rot) => {
  const q = k => { const s = Math.sin(k * 127.1 + sd * 311.7 + P.seed * 74.7) * 43758.5453; return s - Math.floor(s); };
  dc.save(); dc.translate(cx, cy); dc.rotate(rot);
