    const m = 2 + Math.round(shp * 3);
    for (let k = 0; k < m; k++) {
      const r0 = R * (.20 + .66 * q(k * 4 + 1)), w2 = R * (.07 + .18 * q(k * 4 + 2));
      const a0 = q(k * 4 + 3) * 6.283, a1 = a0 + .8 + q(k * 4 + 4) * 3.4;
      dc.moveTo(Math.cos(a0) * (r0 + w2), Math.sin(a0) * (r0 + w2));
