    const m = 3 + Math.round(shp * 5);
    for (let k = 0; k < m; k++) {
      const yy = (k / m - .5) * R * 2.1, h2 = R * (.05 + .22 * q(k * 3 + 1));
      const w2 = R * (.9 + 1.5 * q(k * 3 + 2));
