    const nc = 3 + Math.round(shp * 3), nr = 2 + Math.round(shp * 3);
    const cw = R * 1.9 / nc, ch = R * 1.6 / nr;
    for (let a = 0; a < nc; a++) for (let b = 0; b < nr; b++) {
      if (q(a * 17 + b * 3 + 1) < .28) continue;
      const gp = .12 + .28 * q(a * 5 + b * 11 + 2);
      dc.rect(-R * .95 + a * cw + cw * gp * .5, -R * .8 + b * ch + ch * gp * .5, cw * (1 - gp), ch * (1 - gp));
