    const m = 3 + Math.round(shp * 4);
    for (let k = 0; k < m; k++) {
      const rr = R * (.16 + .40 * q(k * 4 + 1));
      const aa = q(k * 4 + 2) * 6.283, dd = R * .78 * Math.sqrt(q(k * 4 + 3));
      dc.moveTo(Math.cos(aa) * dd + rr, Math.sin(aa) * dd);
      dc.arc(Math.cos(aa) * dd, Math.sin(aa) * dd, rr, 0, 6.2832);
    }
