    const m = 16 + Math.round(shp * 12);
    dc.moveTo(-R, -R * .85);
    for (let k = 0; k <= m; k++) {
      const tt = k / m;
      dc.lineTo(-R + tt * R * 2, -R * .85 + (q(k + 1) - .5) * R * .30 + Math.sin(tt * 7.1 + q(9) * 6) * R * .12);
