// ---- draw --------------------------------------------------------------------
const oldA = dc.globalAlpha;
blendMode(BLEND);
noStroke();
dc.globalAlpha = la;
dc.fillStyle = stock; dc.fillRect(0, 0, W, H);
if (st === 'duotone') blendMode(MULTIPLY);

let bh = hb, bs = .9, bv = .7, bth = 0;
for (let j = NL - 1; j >= 0; j--) {
  const i = idx - j;
  const prog = j === 0 ? prog0 : 1;
  const op = (j === NL - 1 && NL > 1) ? (1 - prog0) : 1;
  if (op < .006 || prog < .002) continue;
  const r1 = fr(i * 3.1 + 1), r2 = fr(i * 3.1 + 2), r3 = fr(i * 3.1 + 3), r4 = fr(i * 3.1 + 4), r5 = fr(i * 3.1 + 5);
  const ink = INKS[Math.floor(r1 * NI) % NI];
  let ih = hb + ink[0], is = ink[1] / 100, iv = ink[2] / 100;
  if (st === 'negative') { is *= .22; iv = .15 + iv * .11; }
  const arch = Math.floor(r2 * 6) % 6;
  const th = (Math.floor(r3 * 4) * 90 + (r4 - .5) * 16) * Math.PI / 180;
  const reg = u * .012 * (.4 + en) * (r5 - .5);
  const cx = W * (P.x + (r1 - .5) * .40) + jx + reg;
  const cy = H * (P.y + (r2 - .5) * .40) + jy + reg * .7;
  const R = u * (.24 + .30 * r3) * sz;
  if (j === 0) { bh = ih; bs = is; bv = iv; bth = th; }

  dc.save();
  // clip to the part of the screen the squeegee has already crossed
  dc.save(); dc.translate(W * .5, H * .5); dc.rotate(th);
  dc.beginPath(); dc.rect(-L * .5, -L * .5, L * prog, L);
  dc.restore();
  dc.clip();
  dc.globalAlpha = la * op;

  dc.beginPath();
  if (st === 'negative') dc.rect(0, 0, W, H);
  stencil(arch, i * 7.3 + 2, cx, cy, R, (r4 - .5) * 2.2);
  if (st === 'puff') { dc.shadowColor = 'rgba(0,0,0,0.6)'; dc.shadowBlur = u * .022; dc.shadowOffsetY = u * .009; }
  dc.fillStyle = css(ih, is, iv, 1);
  dc.fill(st === 'negative' ? 'evenodd' : 'nonzero');
  dc.shadowBlur = 0; dc.shadowOffsetY = 0;
  dc.clip(st === 'negative' ? 'evenodd' : 'nonzero');

  // everything below lands only where this pull actually put ink down
  dc.save(); dc.translate(W * .5, H * .5); dc.rotate(th);
  const qq = k => fr(i * 31.7 + k * 1.7 + 11);
  const nst = 3 + Math.round(sk * 7);
  for (let k = 0; k < nst; k++) {
    const w2 = L * (.008 + .055 * qq(k)), yy = (qq(k + 40) - .5) * L;
    const starve = qq(k + 80) < .45;
    dc.fillStyle = starve ? wipe : css(ih, Math.min(1, is * 1.15), iv * .60, 1);
    dc.globalAlpha = la * op * sk * (.16 + .42 * en) * (.35 + .65 * qq(k + 120));
    dc.fillRect(-L * .5, yy, L, w2);
  }
  // off-contact bloom: the mesh floods just behind the blade
  dc.globalAlpha = la * op * (.10 + .22 * en);
  dc.fillStyle = css(ih, is * .5, Math.min(1, iv * 1.45), 1);
  dc.fillRect(-L * .5 + L * prog - L * .05, -L * .5, L * .05, L);
  dc.restore();
  // pinholes and blocked mesh: ink simply never made it through
  dc.globalAlpha = la * op * (.45 + .45 * sk);
  dc.fillStyle = wipe;
  const nph = 5 + Math.round(sk * 14);
  const qp = k => fr(i * 19.3 + k * 2.7 + 47);
  for (let k = 0; k < nph; k++) {
    const pr = u * (.002 + .014 * qp(k) * qp(k + 90));
    dc.beginPath(); dc.arc(qp(k + 30) * W, qp(k + 60) * H, pr, 0, 6.2832); dc.fill();
