    const c0 = clp(.5 + .42 * Math.sin(sph), .06, .94);
    const gg = dc.createLinearGradient(0, 0, W, H);
    gg.addColorStop(Math.max(0, c0 - .22), 'rgba(255,255,255,0)');
    gg.addColorStop(c0, 'rgba(255,255,255,' + (.28 + .42 * en).toFixed(3) + ')');
    gg.addColorStop(Math.min(1, c0 + .22), 'rgba(255,255,255,0)');
    dc.globalAlpha = la * op; dc.fillStyle = gg; dc.fillRect(0, 0, W, H);
