blendMode(BLEND);

// ---- the squeegee itself, mid-pull ------------------------------------------
dc.save();
dc.translate(W * .5, H * .5); dc.rotate(bth);
const xb = -L * .5 + L * prog0;
const bead = L * .008 * (1 + en * 1.4) * (1 + .3 * K.pulse + .45 * A.bass);
dc.globalAlpha = la * .85;
dc.fillStyle = css(bh, bs * .8, Math.min(1, bv * 1.25), 1); dc.fillRect(xb, -L * .5, bead, L);
dc.globalAlpha = la * .5;
dc.fillStyle = css(bh, bs, bv * .5, 1); dc.fillRect(xb + bead, -L * .5, bead * 2.2, L);
dc.globalAlpha = la * .78;
dc.fillStyle = 'rgba(14,12,16,1)'; dc.fillRect(xb + bead * 3.2, -L * .5, L * .016, L);
const sg = dc.createLinearGradient(xb + bead * 3.2 + L * .016, 0, xb + bead * 3.2 + L * .075, 0);
sg.addColorStop(0, 'rgba(0,0,0,0.45)'); sg.addColorStop(1, 'rgba(0,0,0,0)');
dc.globalAlpha = la; dc.fillStyle = sg; dc.fillRect(xb + bead * 3.2 + L * .016, -L * .5, L * .075, L);
dc.restore();

// ---- stock fibre + screen mesh, then the press-bed falloff -------------------
blendMode(MULTIPLY);
dc.globalAlpha = la * .95;
dc.drawImage(S.tile.drawingContext.canvas, 0, 0, W, H);
blendMode(BLEND);
const vg = dc.createRadialGradient(W * .5, H * .5, u * .18, W * .5, H * .5, diag * .62);
vg.addColorStop(0, 'rgba(0,0,0,0)'); vg.addColorStop(1, 'rgba(8,6,10,0.5)');
dc.globalAlpha = la; dc.fillStyle = vg; dc.fillRect(0, 0, W, H);

dc.globalAlpha = oldA;
blendMode(BLEND);
dc.shadowBlur = 0;
